import React, { useState, useEffect } from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import { Layout } from "antd";
import { Content } from "antd/es/layout/layout";  // <-- Navbar
import Home from "./Home/Home";
import Faculty from "./Faculty/Faculty";
import AddFaculty from "./Faculty/AddFaculty";
import FacultyInfo from "./Faculty/FacultyInfo";
import Scoreboard from "./ScoreBoard/ScoreBoard";
import ReportPage from "./Report/Report";
import Meenties from "./Meenties/Meenties";
import './design/App.css';
import AppNav from "./essential/AppNav";
import AddMeenties from "./Meenties/AddMeenties";
import Login from "./Security/login";
import MainLayout from "./Security/MainLayout";
import AuthLayout from "./Security/AuthLayout";

export default function App() {
  const [darkMode, setDarkMode] = useState(
    localStorage.getItem("theme") === "dark"
  );

  useEffect(() => {
    document.body.className = darkMode ? "dark" : "light";
    localStorage.setItem("theme", darkMode ? "dark" : "light");
  }, [darkMode]);

  return (
    <Routes>
      {/* Auth pages without navbar */}
      <Route
        path="/"
        element={
          <AuthLayout>
            <Login />
          </AuthLayout>
        }
      />

      <Route
        path="/Addfaculty"
        element={
          <AuthLayout>
            <AddFaculty mode={darkMode} />
          </AuthLayout>
        }
      />

      {/* Main app pages with navbar */}
      <Route
        path="/faculty"
        element={
          <MainLayout darkMode={darkMode} toggleDarkMode={() => setDarkMode(!darkMode)}>
            <Faculty mode={darkMode} />
          </MainLayout>
        }
      />
      <Route
        path="/scoreboard"
        element={
          <MainLayout darkMode={darkMode} toggleDarkMode={() => setDarkMode(!darkMode)}>
            <Scoreboard />
          </MainLayout>
        }
      />
      {/* <Route
        path="/Addfaculty"
        element={
          <MainLayout darkMode={darkMode} toggleDarkMode={() => setDarkMode(!darkMode)}>
            <AddFaculty mode={darkMode} />
          </MainLayout>
        }
      /> */}
      <Route
        path="/Facultyinfo/:id"
        element={
          <MainLayout darkMode={darkMode} toggleDarkMode={() => setDarkMode(!darkMode)}>
            <FacultyInfo />
          </MainLayout>
        }
      />
      <Route
        path="/Meenties"
        element={
          <MainLayout darkMode={darkMode} toggleDarkMode={() => setDarkMode(!darkMode)}>
            <Meenties />
          </MainLayout>
        }
      />
      <Route
        path="/AddMeenties"
        element={
          <MainLayout darkMode={darkMode} toggleDarkMode={() => setDarkMode(!darkMode)}>
            <AddMeenties />
          </MainLayout>
        }
      />
      <Route
        path="/Report"
        element={
          <MainLayout darkMode={darkMode} toggleDarkMode={() => setDarkMode(!darkMode)}>
            <ReportPage />
          </MainLayout>
        }
      />
    </Routes>
  );
}
