import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

function Login() {
    const [username, setUsername] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");
    const navigate = useNavigate();

    const handleRegister = () => {
        navigate("/Addfaculty"); // 👈 Navigate to registration page
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {

            // 🔑 If using Basic Auth:
            const response = await axios.post(
                process.env.REACT_APP_API_URL + "/auth/login",
                { username, password },
                {
                    headers: {
                        Authorization: "Basic " + btoa(username + ":" + password),
                    },
                }
            );
            // const payload ={
            //     username,
            //     password
            // }

            // If backend returns a JWT:
            // Api("POST", "/api/faculty", payload)
            // .then((response) => {
            //     const data = response.data
            //     if (response.status === 200) {
            //         localStorage.setItem("token", response.data.token);
            //         AppNotification(MessageType.SUCCESS, "Success", "Data Successfully Upload ")
            //         navigate("/faculty");
            //         reset();
            //         setFileNames({ image: "No file selected" });
            //     }
            // })
            // .catch((error) => {
            //     AppNotification(MessageType.ERROR, "Error", error)
            // });
            if (response.data.token) {
                localStorage.setItem("token", response.data.token);
            }

            navigate("/faculty"); // redirect after login
        } catch (err) {
            setError("Invalid username or password");
            console.error("Login error:", err);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100">
            <div className="bg-white p-8 rounded-2xl shadow-md w-full max-w-sm">
                <h2 className="text-2xl font-bold text-center mb-6">Login</h2>
                {error && <p className="text-red-500 text-sm mb-4">{error}</p>}

                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-gray-700 text-sm mb-2">Username</label>
                        <input
                            type="text"
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring focus:ring-blue-300"
                            required
                        />
                    </div>

                    <div className="mb-6">
                        <label className="block text-gray-700 text-sm mb-2">Password</label>
                        <input
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring focus:ring-blue-300"
                            required
                        />
                    </div>

                    <button
                        type="submit"
                        className="w-full bg-blue-500 text-white py-2 px-4 rounded-lg hover:bg-blue-600 transition"
                    >
                        Login
                    </button>
                </form>
                <p>Don’t have an account?</p>
                <button onClick={handleRegister}>Register</button>
                {/* </div> */}
            </div>
        </div>
    );
}

export default Login;
